package com.example.Hospital.Management.System.repositories; import com.example.Hospital.Management.System.entities.Patient; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface PatientRepository extends JpaRepository<Patient,Long>{List<Patient> findByIsActiveTrue(); long countByHospitalIdAndIsActiveTrue(Long id); @Query("select distinct p from Patient p join p.admissions a where p.isActive=true and a.isActive=true and a.dischargeDate is null and a.room.floor=:floor") List<Patient> admittedOnFloor(@Param("floor") Integer floor); @Query("select distinct p from Patient p join p.bills b where p.isActive=true and b.isActive=true and upper(b.status)='UNPAID'") List<Patient> withOutstandingBills();}
